    out.position = vec4<f32>(at.x / canvas.x * 2.0 - 1.0, 1.0 - at.y / canvas.y * 2.0, 0.0, 1.0);
    out.local = local;
    out.uv = quad.uv.xy + (local / max(size, vec2<f32>(0.0001)) + vec2<f32>(0.5)) * quad.uv.zw;
    out.index = index;
    out.lod = select(base_lod, max(0.0, base_lod - interface_quads.canvas.z), quad.mode == IMAGE || quad.mode == ICON);
    return out;
}

fn framed_image(quad: Quad) -> bool {
    return quad.mode == IMAGE && (quad.case_color != 0u || quad.radius > 0.0);
}

fn doubled(quad: Quad) -> bool {
    if quad.mode == IMAGE {
        return quad.stroke_inset > 0.5;
    }
    return quad.uv.y > 0.5;
}

fn lod_of(scale: f32) -> f32 {
    return max(0.0, -log2(max(scale, 0.0001)));
}

struct Quad {
    rect: vec4<f32>,
    uv: vec4<f32>,
    fill: u32,
    edge: u32,
    mode: u32,
    radius: f32,
    stroke_width: f32,
    stroke_inset: f32,
    scale: f32,
    angle: f32,
    case_color: u32,
    case_grow: f32,
    case_offset: vec2<f32>,
    rim: u32,
    rim_grow: f32,
    align: vec2<u32>
}

struct InterfaceQuads {
    canvas: vec4<f32>,
    quads: array<Quad>
}

@group(2) @binding(0)
var<storage, read> interface_quads: InterfaceQuads;

@group(2) @binding(1)
var interface_icons: texture_2d<f32>;

@group(2) @binding(2)
var interface_glyphs_0: texture_2d<f32>;

@group(2) @binding(3)
var interface_glyphs_1: texture_2d<f32>;

@group(2) @binding(4)
var interface_picture_0: texture_2d<f32>;

@group(2) @binding(5)
var interface_picture_1: texture_2d<f32>;

@group(2) @binding(6)
var interface_picture_2: texture_2d<f32>;

@group(2) @binding(7)
var interface_picture_3: texture_2d<f32>;

@group(2) @binding(8)
var interface_picture_4: texture_2d<f32>;

@group(2) @binding(9)
var interface_picture_5: texture_2d<f32>;

@group(2) @binding(10)
var interface_picture_6: texture_2d<f32>;

@group(2) @binding(11)
var interface_picture_7: texture_2d<f32>;

@group(2) @binding(12)
var interface_picture_8: texture_2d<f32>;

@group(2) @binding(13)
var interface_picture_9: texture_2d<f32>;

@group(2) @binding(14)
var interface_picture_10: texture_2d<f32>;

@group(2) @binding(15)
var interface_picture_11: texture_2d<f32>;

@group(2) @binding(16)
var interface_sampler: sampler;

const PLATE: u32 = 0u;

const ICON: u32 = 1u;

const IMAGE: u32 = 3u;

struct Corner {
    @builtin(position)
    position: vec4<f32>,
    @location(0)
    local: vec2<f32>,
    @location(1)
    uv: vec2<f32>,
    @location(2) @interpolate(flat)
    index: u32,
    @location(3) @interpolate(flat)
    lod: f32
}

fn framed_image(quad: Quad) -> bool {
    return quad.mode == IMAGE && (quad.case_color != 0u || quad.radius > 0.0);
}

fn doubled(quad: Quad) -> bool {
    if quad.mode == IMAGE {
        return quad.stroke_inset > 0.5;
    }
    return quad.uv.y > 0.5;
}

fn rounded_box(point: vec2<f32>, half: vec2<f32>, radius: f32) -> f32 {
    let r = clamp(radius, 0.0, min(half.x, half.y));
    let q = abs(point) - half + vec2<f32>(r);
    return length(max(q, vec2<f32>(0.0))) + min(max(q.x, q.y), 0.0) - r;
}

fn coverage(distance: f32) -> f32 {
    return clamp(0.5 - distance, 0.0, 1.0);
}

fn over(top: vec4<f32>, below: vec4<f32>) -> vec4<f32> {
    return top + below * (1.0 - top.a);
}

fn premultiplied(color: vec4<f32>, amount: f32) -> vec4<f32> {
    let a = color.a * amount;
    return vec4<f32>(color.rgb * a, a);
}

fn cased(quad: Quad, local: vec2<f32>, soft: f32, shown: vec4<f32>, base_d: f32) -> vec4<f32> {
    if quad.case_color == 0u || shown.a >= 1.0 {
        return shown;
    }
    let half = quad.rect.zw * 0.5;
    let grown = half + vec2<f32>(quad.case_grow);
    let rounding = quad.radius + quad.case_grow;
    let shiftable = quad.radius >= 0.0 && quad.case_grow >= 0.0;
    let centered = quad.case_offset.x == 0.0 && quad.case_offset.y == 0.0;
    let color = unpack4x8unorm(quad.case_color);
    var offset_d = base_d - quad.case_grow;
    if !(shiftable && centered) {
        offset_d = rounded_box(local - quad.case_offset, grown, rounding);
    }
    var under = color.a * coverage(offset_d / soft);
    if doubled(quad) {
        var center_d = base_d - quad.case_grow;
        if !shiftable {
            center_d = rounded_box(local, grown, rounding);
        }
        let again = color.a * coverage(center_d / soft);
        under = under + again - under * again;
    }
    var below = vec4<f32>(color.rgb * under, under);
    if quad.rim != 0u {
        let rim = unpack4x8unorm(quad.rim);
        var rim_d = base_d - quad.rim_grow;
        if !(quad.radius >= 0.0 && quad.rim_grow >= 0.0) {
            rim_d = rounded_box(local, half + vec2<f32>(quad.rim_grow), quad.radius + quad.rim_grow);
        }
        let ring = rim.a * coverage(rim_d / soft);
        below = over(vec4<f32>(rim.rgb * ring, ring), below);
    }
    return over(shown, below);
}

fn plate(quad: Quad, local: vec2<f32>) -> vec4<f32> {
    let half = quad.rect.zw * 0.5;
    let base_d = rounded_box(local, half, quad.radius);
    var shown = vec4<f32>(0.0);
    if (quad.fill >> 24u) != 0u {
        let inside = coverage(base_d / quad.scale);
        shown = premultiplied(unpack4x8unorm(quad.fill), inside);
    }
    if quad.stroke_width > 0.0 {
        let inset = quad.stroke_inset;
        let min_half = min(half.x, half.y);
        var outer_d = base_d + inset;
        if !(inset == 0.0 || (quad.radius >= inset && quad.radius <= min_half)) {
            outer_d = rounded_box(local, half - vec2<f32>(inset), quad.radius - inset);
        }
        let outer = coverage(outer_d);
        let deep = inset + quad.stroke_width;
        var inner_d = base_d + deep;
        if !(quad.radius >= deep && quad.radius <= min_half) {
            inner_d = rounded_box(local, half - vec2<f32>(deep), quad.radius - deep);
        }
        let inner = coverage(inner_d);
        shown = over(premultiplied(unpack4x8unorm(quad.edge), max(outer - inner, 0.0)), shown);
    }
    shown = cased(quad, local, quad.scale, shown, base_d);
    if quad.uv.x > 0.0 {
        let turn = fract(atan2(local.x, -local.y) / 6.2831853 + 1.0);
        shown = shown * select(0.0, 1.0, turn <= 1.0 - quad.uv.x);
    }
    return shown;
}

fn encoded(linear: vec3<f32>) -> vec3<f32> {
    let low = linear * 12.92;
    let high = 1.055 * pow(max(linear, vec3<f32>(0.0)), vec3<f32>(1.0 / 2.4)) - vec3<f32>(0.055);
    return select(high, low, linear <= vec3<f32>(0.0031308));
}

fn sampled(picture: texture_2d<f32>, uv: vec2<f32>, lod: f32) -> vec4<f32> {
    let texels = vec2<f32>(textureDimensions(picture));
    return textureSampleLevel(picture, interface_sampler, uv / texels, lod);
}

fn picture_of(slot: u32, uv: vec2<f32>, lod: f32) -> vec4<f32> {
    switch slot {
        case 0u {
            return sampled(interface_picture_0, uv, lod);
        }
        case 1u {
            return sampled(interface_picture_1, uv, lod);
        }
        case 2u {
            return sampled(interface_picture_2, uv, lod);
        }
        case 3u {
            return sampled(interface_picture_3, uv, lod);
        }
        case 4u {
            return sampled(interface_picture_4, uv, lod);
        }
        case 5u {
            return sampled(interface_picture_5, uv, lod);
        }
        case 6u {
            return sampled(interface_picture_6, uv, lod);
        }
        case 7u {
            return sampled(interface_picture_7, uv, lod);
        }
        case 8u {
            return sampled(interface_picture_8, uv, lod);
        }
        case 9u {
            return sampled(interface_picture_9, uv, lod);
        }
        case 10u {
            return sampled(interface_picture_10, uv, lod);
        }
        case default {
            return sampled(interface_picture_11, uv, lod);
        }
    }
}

fn glyph_of(slot: u32, uv: vec2<f32>, lod: f32) -> f32 {
    switch slot {
        case 0u {
            return sampled(interface_glyphs_0, uv, lod).r;
        }
        case default {
            return sampled(interface_glyphs_1, uv, lod).r;
        }
    }
}

@fragment
fn fs_interface(corner: Corner) -> @location(0) vec4<f32> {
    let quad = interface_quads.quads[corner.index];
    var out: vec4<f32>;
    if quad.mode == PLATE {
        out = plate(quad, corner.local);
    }
    else if quad.mode == IMAGE {
        let picture = picture_of(quad.edge, corner.uv, corner.lod);
        let framed = framed_image(quad);
        if picture.a <= 0.0 && !framed {
            discard;
        }
        let tint = unpack4x8unorm(quad.fill);
        var shown = vec3<f32>(0.0);
        if picture.a > 0.0 {
            shown = encoded(picture.rgb);
        }
        if quad.stroke_width > 0.0 {
            let grey = dot(shown, vec3<f32>(0.2126, 0.7152, 0.0722));
            shown = mix(shown, vec3<f32>(grey), quad.stroke_width);
        }
        let tinted = vec4<f32>(shown, picture.a) * tint;
        if !framed {
            out = premultiplied(tinted, 1.0);
        }
        else {
            let base_d = rounded_box(corner.local, quad.rect.zw * 0.5, quad.radius);
            let inside = coverage(base_d);
            out = cased(quad, corner.local, 1.0, premultiplied(tinted, inside), base_d);
        }
    }
    else if quad.mode == ICON {
        let texels = vec2<f32>(textureDimensions(interface_icons));
        let alpha = textureSampleLevel(interface_icons, interface_sampler, corner.uv / texels, corner.lod).a;
        if alpha <= 0.0 {
            discard;
        }
        out = premultiplied(unpack4x8unorm(quad.fill), alpha);
    }
    else {
        let distance = glyph_of(quad.edge, corner.uv, corner.lod);
        let spread = quad.radius;
        let pixels = (distance - 0.5) * 2.0 * spread * quad.scale + quad.stroke_width;
        let alpha = clamp(pixels / (1.0 + quad.stroke_inset) + 0.5, 0.0, 1.0);
        if alpha <= 0.0 {
            discard;
        }
        out = premultiplied(unpack4x8unorm(quad.fill), alpha);
    }
    if out.a <= 0.0 {
        discard;
    }
    return out;
}
